"""
Market Report Model — Market Research Agent Output Storage
Corresponds to Master Specification Section 5 and Section 35 (market_reports table).
"""

import uuid
from typing import Optional
from sqlalchemy import Float, JSON, String, Text
from sqlalchemy.orm import Mapped, mapped_column

from app.core.database import Base
from app.models.base import TenantMixin, TimestampMixin


class MarketReport(Base, TenantMixin, TimestampMixin):
    """Stores structured market research reports generated by the Market Research Agent."""
    __tablename__ = "market_reports"

    id: Mapped[str] = mapped_column(
        String(36),
        primary_key=True,
        default=lambda: str(uuid.uuid4())
    )
    title: Mapped[str] = mapped_column(String(255), nullable=False)
    objective: Mapped[str] = mapped_column(Text, nullable=False)
    industry: Mapped[Optional[str]] = mapped_column(String(100), nullable=True)
    geography: Mapped[str] = mapped_column(String(100), default="India")
    product: Mapped[Optional[str]] = mapped_column(String(100), nullable=True)
    market_summary: Mapped[str] = mapped_column(Text, nullable=False)
    trends: Mapped[list] = mapped_column(JSON, default=list)
    opportunities: Mapped[list] = mapped_column(JSON, default=list)
    threats: Mapped[list] = mapped_column(JSON, default=list)
    recommended_actions: Mapped[list] = mapped_column(JSON, default=list)
    market_size_estimate: Mapped[Optional[str]] = mapped_column(String(100), nullable=True)
    growth_rate: Mapped[Optional[str]] = mapped_column(String(100), nullable=True)
    confidence: Mapped[float] = mapped_column(Float, default=0.85)
    sources: Mapped[list] = mapped_column(JSON, default=list)
